// Embeds database/migrations/*.sql into src/db/migrations.generated.ts so the
// migrations ship inside the API bundle (serverless functions cannot rely on
// reading repository files at runtime). Run via `npm run db:embed`; a test
// fails if the generated file is out of sync with the SQL files.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const apiRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const migrationsDir = path.resolve(apiRoot, '../../database/migrations');
const outFile = path.join(apiRoot, 'src/db/migrations.generated.ts');

export function renderMigrationsModule() {
  const files = readdirSync(migrationsDir).filter((f) => f.endsWith('.sql')).sort();
  const entries = files
    .map((name) => `  {\n    name: ${JSON.stringify(name)},\n    sql: ${JSON.stringify(readFileSync(path.join(migrationsDir, name), 'utf8'))},\n  },`)
    .join('\n');
  return `// GENERATED by scripts/embed-migrations.mjs from database/migrations — do not edit.\nimport type { Migration } from './migrations.js';\n\nexport const MIGRATIONS: readonly Migration[] = [\n${entries}\n];\n`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFileSync(outFile, renderMigrationsModule());
  console.log(`Embedded migrations into ${path.relative(apiRoot, outFile)}`);
}
